    int n = N;

    // Input and output arrays (1D)
    Buffer<num_t, 1> r(n);
    // We'll keep two buffers for y to implement double-buffering.
    Buffer<num_t, 1> y_prev(n);
    Buffer<num_t, 1> y_curr(n);

